<script setup>
import { ref,computed,onMounted,watch } from 'vue'
import AnswerInput from './AnswerInput.vue'
import { useTeaching,copy } from './useTeaching'
const props=defineProps({api:Function,teacher:Boolean,kind:String,initialId:String})
const {busy,error,notice,request,all,run}=useTeaching(props.api)
const records=ref([]),questions=ref([]),selected=ref(null),form=ref(null),practice=ref(null),practiceAnswer=ref([]),result=ref(null),search=ref(''),confirmDelete=ref(false)
const path=computed(()=>({questions:'/questions',papers:'/papers',lessons:'/lesson-plans'}[props.kind]))
const name=computed(()=>({questions:props.teacher?'题库管理':'自主练习',papers:'试卷管理',lessons:'教学设计助教'}[props.kind]))
const visible=computed(()=>records.value.filter(r=>r.title.includes(search.value)))
function defaults(){return {title:'',visibility:'private',data:props.kind==='questions'?{type:'single',stem:'',options:['',''],answer:[],analysis:'',difficulty:'medium',knowledgePoints:[]}:props.kind==='papers'?{items:[]}:{topic:'',audience:'',duration:'',objectives:'',content:''}}}
function create(){selected.value=null;form.value=defaults();practice.value=null;error.value='';notice.value='';confirmDelete.value=false}
const load=async()=>{records.value=await all(path.value);if(props.kind==='papers')questions.value=await all('/questions')}
function open(record){run(async()=>{const data=await request(`${path.value}/${record.id}`);selected.value=data.id;confirmDelete.value=false;if(props.teacher){form.value={title:data.title,visibility:data.visibility,data:copy(data.data)};if(props.kind==='papers')form.value.data.items=data.data.items.map(i=>({questionId:i.questionId,points:i.points}))}else{practice.value=data;practiceAnswer.value=data.data.type==='short'?'':[];result.value=null}})}
async function persist(){const saved=await request(path.value+(selected.value?'/'+selected.value:''),selected.value?'PUT':'POST',form.value);selected.value=saved.id;await load();return saved}
function save(){run(persist,'已保存。')}
function remove(){run(async()=>{await request(`${path.value}/${selected.value}`,'DELETE');selected.value=null;form.value=null;confirmDelete.value=false;await load()},'已删除，已保存的试卷与作业快照不受影响。')}
function changeType(){form.value.data.answer=form.value.data.type==='short'?'':[];form.value.data.options=form.value.data.type==='short'?[]:['','']}
function toggleQuestion(q,checked){if(checked)form.value.data.items.push({questionId:q.id,points:10});else form.value.data.items=form.value.data.items.filter(i=>i.questionId!==q.id)}
function move(index,delta){const items=form.value.data.items;[items[index],items[index+delta]]=[items[index+delta],items[index]]}
function practiceSubmit(){run(async()=>{result.value=await request(`/questions/${practice.value.id}/practice`,'POST',{answer:practiceAnswer.value})})}
function generate(){run(async()=>{const saved=await persist();const generated=await request(`/lesson-plans/${saved.id}/generate`,'POST',{});form.value.data.content=generated.content;notice.value=generated.truncated?'生成已达到长度上限，请检查和补充后保存。':'草案已生成，请检查、编辑后点击保存教案。'})}
function initialize(){selected.value=null;form.value=null;practice.value=null;search.value='';run(async()=>{await load();if(props.initialId&&!props.teacher){practice.value=await request('/questions/'+props.initialId);selected.value=props.initialId;practiceAnswer.value=practice.value.data.type==='short'?'':[];result.value=null}})}
onMounted(initialize)
watch(()=>props.kind,initialize)
</script>
<template><section><div class="work-heading"><div><h2>{{name}}</h2><p>{{kind==='questions'?(teacher?'编写题目与解析，公开的题目可供学生自主练习。':'选择开放题目，完成作答后查看解析。'):kind==='papers'?'从题库选题、设置分值，将试卷用于作业。':'填写教学要求，生成并编辑属于你的教案。'}}</p></div><button v-if="teacher" class="work-primary" :disabled="busy" @click="create">{{kind==='questions'?'新增题目':kind==='papers'?'新建试卷':'新建教案'}}</button></div><p v-if="error" class="work-error" role="alert">{{error}}</p><p v-if="notice" class="work-notice" role="status">{{notice}}</p><p v-if="busy" role="status">{{kind==='lessons'?'正在处理，模型生成可能需要几分钟…':'正在处理…'}}</p><div class="work-grid"><div><label>查找{{kind==='questions'?'题目':kind==='papers'?'试卷':'教案'}}<input v-model="search" placeholder="按标题查找"/></label><div class="work-list work-footer"><button v-for="r in visible" :key="r.id" :disabled="busy" :class="{active:selected===r.id}" @click="open(r)"><strong>{{r.title}}</strong><small>{{r.visibility==='public'?'公开练习':'仅自己可见'}}{{kind==='papers'?' · '+r.data.totalPoints+' 分':''}}</small></button></div><p v-if="!visible.length&&!busy" class="work-muted">暂无内容。</p><button class="work-link work-footer" :disabled="busy" @click="run(load)">刷新列表</button></div><div><form v-if="form&&teacher" class="work-card work-form" @submit.prevent="save"><fieldset :disabled="busy"><h3>{{selected?'编辑':'新建'}}{{kind==='questions'?'题目':kind==='papers'?'试卷':'教案'}}</h3><label>标题<input v-model="form.title" required maxlength="150"/></label><template v-if="kind==='questions'"><div class="work-row"><label>题型<select v-model="form.data.type" @change="changeType"><option value="single">单选题</option><option value="multiple">多选题</option><option value="short">简答题</option></select></label><label>难度<select v-model="form.data.difficulty"><option value="easy">简单</option><option value="medium">中等</option><option value="hard">较难</option></select></label></div><label>题干<textarea v-model="form.data.stem" required maxlength="6000"/></label><template v-if="form.data.type!=='short'"><div v-for="(_,i) in form.data.options" :key="i" class="work-row"><label>选项 {{String.fromCharCode(65+i)}}<input v-model="form.data.options[i]" required maxlength="1000"/></label><label class="work-check"><input :type="form.data.type==='single'?'radio':'checkbox'" name="correct-option" :checked="form.data.answer.includes(i)" @change="form.data.answer=form.data.type==='single'?[i]:$event.target.checked?[...form.data.answer,i]:form.data.answer.filter(n=>n!==i)"/> 正确答案</label></div><div class="work-actions"><button type="button" class="work-button" :disabled="form.data.options.length>=8" @click="form.data.options.push('')">添加选项</button><button type="button" class="work-button" :disabled="form.data.options.length<=2" @click="form.data.options.pop();form.data.answer=form.data.answer.filter(i=>i<form.data.options.length)">移除末项</button></div></template><label v-else>参考答案<textarea v-model="form.data.answer" required maxlength="6000"/></label><label>解析<textarea v-model="form.data.analysis" maxlength="6000"/></label><label>知识点（用中文逗号分隔）<input :value="form.data.knowledgePoints.join('，')" @change="form.data.knowledgePoints=$event.target.value.split(/[,，]/).map(v=>v.trim()).filter(Boolean)"/></label><label>可见范围<select v-model="form.visibility"><option value="private">仅自己可见，用于测验</option><option value="public">公开，学生练习后可查看答案</option></select></label></template>
<template v-else-if="kind==='papers'"><p class="work-muted">请选择题目，再调整题序与分值。</p><p v-if="!questions.length">题库为空，请先在题库管理中新增题目。</p><div class="work-scroll"><label v-for="q in questions" :key="q.id" class="work-check"><input type="checkbox" :checked="form.data.items.some(i=>i.questionId===q.id)" @change="toggleQuestion(q,$event.target.checked)"/>{{q.title}}</label></div><div v-for="(item,i) in form.data.items" :key="item.questionId" class="work-card"><strong>{{i+1}}. {{questions.find(q=>q.id===item.questionId)?.title||'原题已删除，请移除后重新选题'}}</strong><label>分值<input v-model.number="item.points" type="number" min="1" max="100" required/></label><div class="work-actions work-footer"><button type="button" class="work-button" :disabled="i===0" @click="move(i,-1)">上移</button><button type="button" class="work-button" :disabled="i===form.data.items.length-1" @click="move(i,1)">下移</button><button type="button" class="work-button" @click="form.data.items.splice(i,1)">移除</button></div></div><p>共 {{form.data.items.length}} 题 · {{form.data.items.reduce((sum,i)=>sum+(Number(i.points)||0),0)}} 分</p></template>
<template v-else><label>教学主题<input v-model="form.data.topic" required maxlength="150"/></label><div class="work-row"><label>授课对象<input v-model="form.data.audience" required maxlength="150" placeholder="例如：教育技术本科一年级"/></label><label>课时安排<input v-model="form.data.duration" required maxlength="100" placeholder="例如：45 分钟"/></label></div><label>教学目标<textarea v-model="form.data.objectives" required maxlength="2000"/></label><button type="button" class="work-button" @click="generate">保存要求并生成草案</button><label>教案正文<textarea v-model="form.data.content" class="long-text" maxlength="20000" placeholder="可手动编写，也可生成后继续编辑。"/></label></template><div class="work-actions"><button class="work-primary">{{kind==='lessons'?'保存教案':'保存'}}</button><button type="button" class="work-button" @click="form=null;selected=null">关闭编辑</button><button v-if="selected" type="button" class="work-danger" @click="confirmDelete=true">删除</button></div><div v-if="confirmDelete" class="work-error">确定删除此内容？<div class="work-actions"><button type="button" class="work-danger" @click="remove">确认删除</button><button type="button" @click="confirmDelete=false">取消</button></div></div></fieldset></form>
<form v-else-if="practice" class="work-card work-form" @submit.prevent="practiceSubmit"><h3>{{practice.title}}</h3><p class="work-stem">{{practice.data.stem}}</p><AnswerInput :question="practice.data" v-model="practiceAnswer" name="practice" :disabled="busy"/><button class="work-primary" :disabled="busy">提交练习并查看解析</button><div v-if="result" class="work-result"><strong>{{result.correct===null?'请对照参考答案自评':result.correct?'回答正确':'再想一想'}}</strong><p>参考答案：{{Array.isArray(result.answer)?result.answer.map(i=>String.fromCharCode(65+i)).join('、'):result.answer}}</p><p>{{result.analysis}}</p></div></form><div v-else class="work-empty">{{teacher?'从左侧选择内容，或创建新的内容。':'从左侧选择一道题开始练习。'}}</div></div></div></section></template>
